        return head;
    }
};

// --- Test Driver ---
void printList(ListNode* head) {
    cout << "[";
    while (head) {
        cout << head->val;
        if (head->next) cout << ",";
        head = head->next;
    }
    cout << "]" << endl;
}

int main() {
    ListNode* head = new ListNode(1, new ListNode(2, new ListNode(3, new ListNode(4, new ListNode(5)))));
    cout << "Original:" << endl;
    printList(head);

    Solution s;
    ListNode* newHead = s.reverseList(head);

    cout << "Reversed:" << endl;
    printList(newHead);
    return 0;
}

